+          status.textContent = "Thanks — your message has been queued.";
+          renderApp();
+          form.reset();
+          state.values = { fullName: "", email: "", phone: "" };
+          state.errors = {};
+          state.submitted = false;
+          renderApp();
+        });
+      }
+
+      function escapeHtml(value) {
+        return String(value)
+          .replaceAll("&", "&amp;")
+          .replaceAll("<", "&lt;")
+          .replaceAll(">", "&gt;")
+          .replaceAll('"', "&quot;");
+      }
+
+      renderApp();
+    </script>
+  </body>
+</html>
+

')

