        border: 1px solid rgba(159, 181, 255, 0.16);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
        padding: 28px;
      }

      form {
        display: grid;
        gap: 18px;
      }

      .form-field {
        display: grid;
        gap: 8px;
