        --danger: #ff7b8a;
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.35);
        --radius: 18px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(124, 156, 255, 0.2), transparent 34%),
          linear-gradient(180deg, #09101f 0%, var(--bg) 100%);
        color: var(--text);
        display: grid;
        place-items: center;
        padding: 32px 16px;
      }

      .support-shell {
        width: min(100%, 720px);
      }

      .hero {
        margin-bottom: 18px;
      }

      .eyebrow {
        margin: 0 0 8px;
        color: var(--accent-2);
        text-transform: uppercase;
        letter-spacing: 0.14em;
        font-size: 0.78rem;
        font-weight: 700;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 4vw, 3rem);
        line-height: 1.08;
      }

      .hero p {
        margin: 10px 0 0;
        max-width: 58ch;
        color: var(--muted);
        line-height: 1.6;
      }

      .card {
        margin-top: 24px;
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.01)), var(--panel);
        border: 1px solid rgba(159, 181, 255, 0.16);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
        padding: 28px;
      }

      form {
        display: grid;
        gap: 18px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-weight: 600;
        color: var(--text);
      }

      .field-row {
        position: relative;
      }

      input {
        width: 100%;
        appearance: none;
        border: 1px solid var(--border);
        border-radius: 14px;
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0.01)), var(--panel-2);
        color: var(--text);
        padding: 14px 16px;
        font: inherit;
        outline: none;
        transition: border-color 120ms ease, box-shadow 120ms ease, transform 120ms ease;
      }

      input::placeholder {
        color: #7f8aae;
      }

      input:focus {
        border-color: rgba(124, 156, 255, 0.9);
        box-shadow: 0 0 0 4px rgba(124, 156, 255, 0.15);
      }

      input[aria-invalid="true"] {
        border-color: rgba(255, 123, 138, 0.95);
        box-shadow: 0 0 0 4px rgba(255, 123, 138, 0.12);
      }

      .helper,
      .error {
        margin: 0;
        font-size: 0.92rem;
        line-height: 1.45;
      }

      .helper {
        color: var(--muted);
      }

      .error {
        color: var(--danger);
        min-height: 1.35em;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        padding-top: 4px;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 14px 22px;
        background: linear-gradient(135deg, #87a3ff, #6c7dff);
        color: #081023;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 14px 36px rgba(108, 125, 255, 0.28);
        transition: transform 120ms ease, box-shadow 120ms ease, filter 120ms ease;
      }

      button:hover {
        transform: translateY(-1px);
        filter: brightness(1.04);
      }

      button:focus {
        outline: none;
        box-shadow: 0 0 0 4px rgba(124, 156, 255, 0.18), 0 14px 36px rgba(108, 125, 255, 0.28);
      }

      .status {
        margin: 16px 0 0;
        color: var(--muted);
        min-height: 1.5em;
      }

      @media (max-width: 640px) {
        .card {
          padding: 20px;
        }

        .actions {
          justify-content: stretch;
        }

        button {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
    <main class="support-shell">
      <div id="app"></div>
    </main>

    <script>
      const state = {
        submitted: false,
        touched: {
          fullName: false,
          email: false,
          phone: false
        },
        values: {
          fullName: "",
          email: "",
          phone: ""
        },
        errors: {},
        statusMessage: ""
      };

      const phonePattern = /^(?:\+?\d{1,3}[-.\s]?)?(?:\(?\d{3}\)?[-.\s]?)\d{3}[-.\s]?\d{4}$/;
      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

      function supportFormTitle() {
        return `
          <section class="hero" aria-labelledby="support-form-title">
            <p class="eyebrow">Support</p>
            <h1 id="support-form-title">Contact our team</h1>
            <p>Send us your details and we’ll get back to you as soon as possible.</p>
          </section>
        `;
      }

      function fieldMarkup({ id, label, type, value, placeholder, helper, error, required, autocomplete, inputmode }) {
        const invalid = Boolean(error);
        const describedBy = [
          helper ? `${id}-help` : null,
          invalid ? `${id}-error` : null
        ].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label for="${id}">${label}${required ? " *" : ""}</label>
            <div class="field-row">
              <input
                id="${id}"
                name="${id}"
                type="${type}"
                value="${escapeHtml(value)}"
                placeholder="${placeholder}"
                ${required ? "required" : ""}
                ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
                ${inputmode ? `inputmode="${inputmode}"` : ""}
                aria-invalid="${invalid}"
                ${describedBy ? `aria-describedby="${describedBy}"` : ""}
              />
            </div>
            ${helper ? `<p class="helper" id="${id}-help">${helper}</p>` : ""}
            <p class="error" id="${id}-error" aria-live="polite">${error || ""}</p>
          </div>
        `;
      }

      function validate(values) {
        const errors = {};

        if (!values.fullName.trim()) {
          errors.fullName = "Full name is required.";
        }

        if (!values.email.trim()) {
          errors.email = "Email address is required.";
        } else if (!emailPattern.test(values.email.trim())) {
          errors.email = "Enter a valid email address.";
        }

        if (values.phone.trim() && !phonePattern.test(values.phone.trim())) {
          errors.phone = "Enter a valid phone number in the expected format.";
        }

        return errors;
      }

      function syncErrors(fields) {
        const nextErrors = validate(state.values);
        fields.forEach((field) => {
          if (nextErrors[field]) {
            state.errors[field] = nextErrors[field];
          } else {
            delete state.errors[field];
          }
        });
      }

      function renderApp() {
        const app = document.getElementById("app");
        const values = state.values;
        const errors = state.errors;

        app.innerHTML = `
          ${supportFormTitle()}
          <section class="card" aria-labelledby="support-form-title">
            <form id="support-form" novalidate>
              ${fieldMarkup({
                id: "fullName",
                label: "Full name",
                type: "text",
                value: values.fullName,
                placeholder: "Jane Doe",
                error: errors.fullName,
                required: true,
                autocomplete: "name"
              })}
              ${fieldMarkup({
                id: "email",
                label: "Email address",
                type: "email",
                value: values.email,
                placeholder: "jane@example.com",
                error: errors.email,
                required: true,
                autocomplete: "email",
                inputmode: "email"
              })}
              ${fieldMarkup({
                id: "phone",
                label: "Phone number",
                type: "tel",
                value: values.phone,
                placeholder: "(555) 123-4567",
                helper: "Optional. Use the format (555) 123-4567 or +1 555 123 4567.",
                error: errors.phone,
                required: false,
                autocomplete: "tel",
                inputmode: "tel"
              })}
              <div class="actions">
                <button type="submit">Submit</button>
              </div>
            </form>
            <p class="status" id="form-status" aria-live="polite">
              ${state.statusMessage}
            </p>
          </section>
        `;

        bindEvents();
      }

      function bindEvents() {
        const form = document.getElementById("support-form");

        ["fullName", "email", "phone"].forEach((name) => {
          const input = document.getElementById(name);
          input.addEventListener("input", (event) => {
            state.values[name] = event.target.value;
            state.statusMessage = "";
            if (state.submitted || state.touched[name]) {
              syncErrors(state.submitted ? ["fullName", "email", "phone"] : [name]);
              renderApp();
            }
          });

          input.addEventListener("blur", () => {
            state.touched[name] = true;
            syncErrors([name]);
            renderApp();
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          state.submitted = true;
          state.touched = { fullName: true, email: true, phone: true };
          syncErrors(["fullName", "email", "phone"]);

          if (Object.keys(state.errors).length > 0) {
            state.statusMessage = "Please fix the highlighted fields.";
            renderApp();
            const firstInvalid = document.querySelector('[aria-invalid="true"]');
            if (firstInvalid) firstInvalid.focus();
            return;
          }

          state.statusMessage = "Thanks — your message has been queued.";
          state.values = { fullName: "", email: "", phone: "" };
          state.errors = {};
          state.touched = { fullName: false, email: false, phone: false };
          state.submitted = false;
          renderApp();
        });
      }

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;");
      }

      renderApp();
    </script>
  </body>
</html>
